#define main idpProgramMain
#include "idp-physical.cpp"
#undef main
#include <unordered_set>
vector<float> tri;vector<float> higher[6];
void loadTri(string dir){ifstream f(dir+"/model3.tsv");string s;float v;f>>s>>v;tri.assign(26*26*26,v);while(f>>s>>v)tri[(s[0]-'a')*676+(s[1]-'a')*26+s[2]-'a']=v;}
void loadHigher(string dir){for(int n=4;n<=5;n++){ifstream f(dir+"/model"+to_string(n)+".tsv");string s;float v;f>>s>>v;int size=1;for(int i=0;i<n;i++)size*=26;higher[n].assign(size,v);while(f>>s>>v){int ix=0;for(char c:s)ix=ix*26+c-'a';higher[n][ix]=v;}}}
struct Path{float score;unsigned int mask;array<unsigned char,22> cols;};
int beamwidth=64;
vector<Path> prune(vector<Path>&all,int len){sort(all.begin(),all.end(),[](auto&a,auto&b){return a.score>b.score;});unordered_set<unsigned long long>seen;vector<Path>out;for(auto&p:all){unsigned long long signature=((unsigned long long)p.mask<<20)|(p.cols[0]<<15)|(p.cols[1]<<10)|(p.cols[len-2]<<5)|p.cols[len-1];if(seen.insert(signature).second){out.push_back(p);if(out.size()==beamwidth)break;}}return out;}
Path reconstruct(const string&s,int w){assert(s.size()%w==0);int h=s.size()/w;float table[22][22][22];for(int a=0;a<w;a++)for(int b=0;b<w;b++)for(int c=0;c<w;c++)if(a!=b&&b!=c&&a!=c){float sc=0;for(int r=0;r<h;r++)sc+=tri[(s[a*h+r]-'a')*676+(s[b*h+r]-'a')*26+s[c*h+r]-'a'];table[a][b][c]=sc;}auto extra=[&](const Path&p,int len,bool front){float sc=0;for(int n=4;n<=5;n++)if(len>=n){for(int r=0;r<h;r++){int ix=0;for(int j=0;j<n;j++){int c=p.cols[front?j:len-n+j];ix=ix*26+s[c*h+r]-'a';}sc+=(n==4?.4f:.8f)*higher[n][ix];}}return sc;};vector<Path>all;for(int a=0;a<w;a++)for(int b=0;b<w;b++)for(int c=0;c<w;c++)if(a!=b&&b!=c&&a!=c){Path p{};p.mask=(1U<<a)|(1U<<b)|(1U<<c);p.cols[0]=a;p.cols[1]=b;p.cols[2]=c;p.score=.15*table[a][b][c];all.push_back(p);}auto beam=prune(all,3);for(int len=3;len<w;len++){all.clear();for(auto&p:beam)for(int c=0;c<w;c++)if(!(p.mask&(1U<<c))){Path next=p;next.mask|=1U<<c;next.cols[len]=c;next.score+=.15*table[p.cols[len-2]][p.cols[len-1]][c]+extra(next,len+1,false);all.push_back(next);next=p;next.mask|=1U<<c;for(int i=len;i>0;i--)next.cols[i]=next.cols[i-1];next.cols[0]=c;next.score+=.15*table[c][p.cols[0]][p.cols[1]]+extra(next,len+1,true);all.push_back(next);}beam=prune(all,len+1);}return beam[0];}
int main(int argc,char**argv){loadTri(argv[1]);loadHigher(argv[1]);ifstream f(argv[2]);string ct;f>>ct;int w1=stoi(argv[3]),w2=stoi(argv[4]);assert(ct.size()%w1==0&&w1<=22);if(argc>5&&string(argv[5])=="score"){auto p=reconstruct(ct,w1);cout<<p.score<<" cols=";for(int i=0;i<w1;i++)cout<<(int)p.cols[i]<<",";cout<<endl;return 0;}int seeds=argc>5?stoi(argv[5]):200;auto ts=transforms(w2);Key k(w2);iota(k.begin(),k.end(),0);vector<Cand>pool;for(int i=0;i<seeds;i++){shuffle(k.begin(),k.end(),rng);pool.push_back({reconstruct(dec(ct,k),w1).score,k});}sort(pool.begin(),pool.end(),[](auto&a,auto&b){return a.sc>b.sc;});pool.resize(min(2,(int)pool.size()));for(int rep=0;rep<(int)pool.size();rep++){auto cand=pool[rep];for(int iteration=0;iteration<6;iteration++){Cand best=cand;for(auto&t:ts){auto kk=inverseKey(transformKey(inverseKey(cand.k),t));float ns=reconstruct(dec(ct,kk),w1).score;if(ns>best.sc+.001)best={ns,kk};}if(best.sc<=cand.sc+.001)break;cand=best;cerr<<"seed="<<rep<<" round="<<iteration<<" trigram_potential="<<cand.sc<<endl;}auto mid=dec(ct,cand.k);auto path=reconstruct(mid,w1);Key k1(w1);for(int i=0;i<w1;i++)k1[path.cols[i]]=i;cout<<rep<<" score="<<cand.sc<<" key1=";for(int x:k1)cout<<x<<",";cout<<" key2=";for(int x:cand.k)cout<<x<<",";cout<<" "<<dec(mid,k1)<<endl;}}
